import PropTypes from "prop-types";
import React from "react";

import applyReducers from "@traveloka/soya-components/lib/legacy/applyReducers";
import {
  commonRulesMapDisToProps,
  commonRulesReducers,
  commonRulesSelector,
} from "./CommonRuleRedux";
import { compose } from "redux";
import { connect } from "react-redux";
import { isValueValid } from "./CommonRuleFunctions";
import { number, required } from "./ValidationUtil";
import { Button } from "@traveloka/soya-components";
import DropdownInput from "./DropdownInput";
import { NotificationManager } from "@traveloka/soya-components";
import TextInput from "./TextInput";

import * as style from "./CommonRule.styles";

class ConditionRightModal extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      existingValue:
        props.existingValue === null
          ? this.getDefaultRightCondition()
          : props.existingValue,
    };
  }

  getDefaultRightCondition = () => {
    const acceptableOutput = [];
    const { ruleStructures, leftValue } = this.props;
    const formatterStructure = JSON.parse(ruleStructures.formatterStructure);
    const expressionStructure = JSON.parse(ruleStructures.expressionStructure);
    const leftFieldOutput = expressionStructure[leftValue].output;
    let value = "";
    if (
      leftFieldOutput === "String" ||
      leftFieldOutput === "Boolean" ||
      leftFieldOutput === "Integer" ||
      leftFieldOutput === "Long"
    ) {
      acceptableOutput.push(leftFieldOutput + "Value");
      if (leftFieldOutput === "Boolean") {
        value = "true";
      }
    } else {
      acceptableOutput.push("DecimalValue");
    }
    for (const j in acceptableOutput) {
      return { root: formatterStructure[acceptableOutput[j]].id, value };
    }
  };

  getRightAdditionalField = () => {
    const { existingValue } = this.state;
    const additionalField = [];
    additionalField.push(
      <div>
        <label>{"Value"}</label>
        <br />
      </div>
    );
    if (existingValue.root === "BooleanValue") {
      const enabledItems = [
        { value: "true", label: "True" },
        { value: "false", label: "False" },
      ];
      additionalField.push(
        <DropdownInput
          value={existingValue.value}
          name="value"
          onChange={this.handleChangeValue}
          items={enabledItems}
        />
      );
    } else if (existingValue.root === "StringValue") {
      additionalField.push(
        <TextInput
          name={"value"}
          placeholder={"value"}
          onChange={this.handleChangeValue}
          validators={[required]}
          value={existingValue.value}
        />
      );
    } else {
      additionalField.push(
        <TextInput
          name={"value"}
          placeholder={"value"}
          onChange={this.handleChangeValue}
          validators={[required, number]}
          value={existingValue.value}
        />
      );
    }
    return additionalField;
  };

  getRightModalFields() {
    const rightOptions = [];
    const acceptableOutput = [];
    const { ruleStructures, leftValue } = this.props;
    const formatterStructure = JSON.parse(ruleStructures.formatterStructure);
    const expressionStructure = JSON.parse(ruleStructures.expressionStructure);
    const leftFieldOutput = expressionStructure[leftValue].output;
    if (
      leftFieldOutput === "String" ||
      leftFieldOutput === "Boolean" ||
      leftFieldOutput === "Integer" ||
      leftFieldOutput === "Long"
    ) {
      acceptableOutput.push(leftFieldOutput + "Value");
    } else {
      acceptableOutput.push("DecimalValue");
    }
    for (const j in acceptableOutput) {
      const option = {
        label: formatterStructure[acceptableOutput[j]].label,
        value: formatterStructure[acceptableOutput[j]].id,
      };
      if (!this.checkIfExistInArray(option, rightOptions)) {
        rightOptions.push(option);
      }
    }
    rightOptions.sort((a, b) => {
      if (a.label > b.label) {
        return 1;
      } else if (b.label > a.label) {
        return -1;
      }
      return 0;
    });
    return rightOptions;
  }

  checkIfExistInArray(obj, arrayObj) {
    for (const i in arrayObj) {
      if (arrayObj[i].label === obj.label && arrayObj[i].value === obj.value) {
        return true;
      }
    }
    return false;
  }

  handleChangeRoot = (name, value) => {
    const existingValue = {};
    existingValue[name] = value;
    this.setState({ existingValue });
  };

  handleChangeValue = (name, value, isValid) => {
    const { existingValue } = this.state;
    existingValue[name] = value;
    this.setState({ existingValue });
  };

  handleCancel = () => {
    const { onCancel } = this.props;
    onCancel();
  };

  handleSave = () => {
    const { onSave } = this.props;
    const { existingValue } = this.state;
    if (isValueValid(existingValue.root, existingValue.value)) {
      const right = {};
      for (const i in existingValue) {
        right[i] = existingValue[i];
      }
      onSave(right);
    } else {
      NotificationManager.showError({
        message: "Input is not valid, please re-check",
        size: "md",
      });
    }
  };

  render() {
    const { existingValue } = this.state;
    const items = this.getRightModalFields();
    const additionalField = this.getRightAdditionalField();
    return (
      <div>
        <div>
          <label>{"Expression"}</label>
          <br />
          <DropdownInput
            value={existingValue.root}
            name="root"
            items={items}
            onChange={this.handleChangeRoot}
          />
        </div>
        <div>{additionalField}</div>
        <div className={style.modalFooter}>
          <Button onClick={this.handleCancel} color="link">
            {"Close"}
          </Button>
          <Button onClick={this.handleSave} color="blue">
            {"OK"}
          </Button>
        </div>
      </div>
    );
  }
}

ConditionRightModal.propTypes = {
  existingValue: PropTypes.shape({
    root: PropTypes.string,
    value: PropTypes.number,
  }),
  leftValue: PropTypes.string.isRequired,
  ruleStructures: PropTypes.string.isRequired,
  onSave: PropTypes.func.isRequired,
  onCancel: PropTypes.func.isRequired,
};

const mapStateToProps = (state, ownProps) => ({
  ruleStructures: commonRulesSelector.getRuleStructures(state),
});

export default compose(
  applyReducers(commonRulesReducers),
  connect(mapStateToProps, commonRulesMapDisToProps)
)(ConditionRightModal);
